// Exact minimum distance of the stabilizer code 33-2-7 (data/codes/33-2-7.json):
// magma -b magma/33-2-7.m
SetQuitOnError(true); SetColumns(0);
SetVerbose("Code", 1);
ma, mi, pa := GetVersion(); printf "Magma V%o.%o-%o\n", ma, mi, pa;
n := 33;
F2 := GF(2);
rows := [];
v := [F2!0 : i in [1..2*n]]; for q in [0, 18, 22] do v[q+1] := 1; end for; for q in [0, 15, 27] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [1, 19, 23] do v[q+1] := 1; end for; for q in [10, 14, 26] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [2, 20, 24] do v[q+1] := 1; end for; for q in [9, 13, 25] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [3, 21, 25] do v[q+1] := 1; end for; for q in [8, 12, 24] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [4, 11, 26] do v[q+1] := 1; end for; for q in [7, 11, 23] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [5, 12, 27] do v[q+1] := 1; end for; for q in [6, 21, 22] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [6, 13, 28] do v[q+1] := 1; end for; for q in [5, 20, 32] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [7, 14, 29] do v[q+1] := 1; end for; for q in [4, 19, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [8, 15, 30] do v[q+1] := 1; end for; for q in [3, 18, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [9, 16, 31] do v[q+1] := 1; end for; for q in [2, 17, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
