v := [F2!0 : i in [1..2*n]]; for q in [0, 11, 29] do v[q+1] := 1; end for; for q in [4, 16, 22] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [1, 12, 30] do v[q+1] := 1; end for; for q in [3, 15, 32] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [2, 13, 31] do v[q+1] := 1; end for; for q in [2, 14, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [3, 14, 32] do v[q+1] := 1; end for; for q in [1, 13, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [4, 15, 22] do v[q+1] := 1; end for; for q in [0, 12, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [5, 16, 23] do v[q+1] := 1; end for; for q in [10, 11, 28] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [6, 17, 24] do v[q+1] := 1; end for; for q in [9, 21, 27] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [7, 18, 25] do v[q+1] := 1; end for; for q in [8, 20, 26] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [8, 19, 26] do v[q+1] := 1; end for; for q in [7, 19, 25] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [9, 20, 27] do v[q+1] := 1; end for; for q in [6, 18, 24] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [10, 21, 28] do v[q+1] := 1; end for; for q in [5, 17, 23] do v[n+q+1] := 1; end for; Append(~rows, v);
