v := [F2!0 : i in [1..2*n]]; for q in [8, 12, 23] do v[q+1] := 1; end for; for q in [4, 21, 25] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [9, 13, 24] do v[q+1] := 1; end for; for q in [3, 20, 24] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [10, 14, 25] do v[q+1] := 1; end for; for q in [2, 19, 23] do v[n+q+1] := 1; end for; Append(~rows, v);
