v := [F2!0 : i in [1..2*n]]; for q in [1, 16, 27] do v[q+1] := 1; end for; for q in [0, 17, 32] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [2, 17, 28] do v[q+1] := 1; end for; for q in [10, 16, 31] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [3, 18, 29] do v[q+1] := 1; end for; for q in [9, 15, 30] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [4, 19, 30] do v[q+1] := 1; end for; for q in [8, 14, 29] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [5, 20, 31] do v[q+1] := 1; end for; for q in [7, 13, 28] do v[n+q+1] := 1; end for; Append(~rows, v);
v := [F2!0 : i in [1..2*n]]; for q in [6, 21, 32] do v[q+1] := 1; end for; for q in [6, 12, 27] do v[n+q+1] := 1; end for; Append(~rows, v);
M := Matrix(F2, rows);
Q := QuantumCode(M : ExtendedFormat := true);
print "code:", Length(Q), Dimension(Q);
assert Length(Q) eq 33 and Dimension(Q) eq 2;
t := Cputime(); d := MinimumDistance(Q); print "MinimumDistance:", d, "cputime:", Cputime(t);
exit;
